def replace_section(text, start_comment, end_comment, replacement):
    pattern = re.escape(start_comment) + r'.*?(?=' + re.escape(end_comment) + r')'
    text, n = re.subn(pattern, replacement + '\n\n', text, count=1, flags=re.S)
    if n != 1:
        raise SystemExit(f'section replacement failed: {start_comment}')
    return text


